class TestSaveBtsConfigurationModal(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.save_bts_configuration_modal = SaveBtsConfigurationModal()
        self.save_bts_configuration_type_str = 'Save as SCF - BTS configuration only'
        self.save_planned_parameter_changes = False

    def test_wait_until_save_bts_configuration_modal_appear(self):
        self.save_bts_configuration_modal.wait_for_visibility = mock.Mock()
        self.save_bts_configuration_modal.wait_until_save_bts_configuration_modal_appear()
        self.save_bts_configuration_modal.wait_for_visibility.assert_called()

    def test_save(self):
        save_configuration_button_xpath = "//div[@class='modal-footer']//ui-button[@a-text='Save']/button"
        expect_bts_configuration_path = "//configuration.xml"

        self.save_bts_configuration_modal._set_save_configuration_type = mock.Mock()
        self.save_bts_configuration_modal.click_enabled_element = mock.Mock()
        self.save_bts_configuration_modal.download_files = mock.MagicMock(return_value=expect_bts_configuration_path)

        output = self.save_bts_configuration_modal.save(self.save_bts_configuration_type_str,
                                                        self.save_planned_parameter_changes)
        self.save_bts_configuration_modal._set_save_configuration_type.assert_called_once_with(
            self.save_bts_configuration_type_str, self.save_planned_parameter_changes)
        self.save_bts_configuration_modal.click_enabled_element.assert_called_once_with(
            (By.XPATH, save_configuration_button_xpath))
        self.save_bts_configuration_modal.download_files.assert_called()
        self.assertEqual(output, expect_bts_configuration_path)

    def test_cancel(self):
        cancel_configuration_button_xpath = "//div[@class='modal-footer']//ui-button[@a-text='Cancel']/button"
        self.save_bts_configuration_modal.click_enabled_element = mock.Mock()

        self.save_bts_configuration_modal.cancel()
        self.save_bts_configuration_modal.click_enabled_element.assert_called_once_with(
            cancel_configuration_button_xpath)

    def test_set_save_configuration_type(self):
        save_planned_parameter_changes_check_xpath = \
            "//div[@class='modal-body']//span[text()='Save also planned parameters changes']"
        self.save_bts_configuration_modal.click_element_by_xpath = mock.Mock()
        self.save_bts_configuration_modal.check_if_exists = mock.Mock(return_value=True)
        self.save_bts_configuration_modal.click_element_by_xpath = mock.Mock()

        self.save_bts_configuration_modal._set_save_configuration_type(self.save_bts_configuration_type_str,
                                                                       self.save_planned_parameter_changes)
        self.save_bts_configuration_modal.click_element_by_xpath. \
            assert_called_with(save_planned_parameter_changes_check_xpath)


