class TestBtsStartUpViewModal(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.Mock()
        self.bts_start_up_view_modal = BtsStartUpViewModal()

    def test_wait_for_start_up_view_modal_appear(self):
        self.bts_start_up_view_modal.wait_until_modal_appear = mock.Mock()

        self.bts_start_up_view_modal.wait_for_start_up_view_modal_appear(60)
        self.bts_start_up_view_modal.wait_until_modal_appear.assert_called_once()

    def test_get_bts_start_up_view_info(self):
        child_elem = mock.Mock()
        child_elem.text = 'test:'
        elem = mock.Mock()
        elem.text = 'a'
        elem.find_elements_by_xpath = mock.Mock(return_value=[child_elem])
        self.bts_start_up_view_modal.driver.find_elements_by_xpath = mock.Mock(return_value=[elem])

        info = self.bts_start_up_view_modal.get_bts_start_up_view_info()
        self.assertEqual(info, {'a': {'test': 'test:'}})
